function pick(map, key) {
  return map[key] || key;
}

function build(locale) {
  return {
    destinations: en.destinations.map((item) => {
      const [title, overview, highlights, tips] = details[item.slug][locale];
      return {
        slug: item.slug,
        region: pick(region[locale], item.region),
        title,
        subtitle: pick(subtitle[locale], item.subtitle),
        duration: pick(duration[locale], item.duration),
        bestTime: pick(bestTime[locale], item.bestTime),
        overview,
        highlights,
        tips,
      };
    }),
  };
}

for (const locale of ["si", "ta"]) {
  const out = path.join(root, `public/data/destinations-${locale}.json`);
  fs.writeFileSync(out, JSON.stringify(build(locale), null, 2) + "\n");
  console.log("wrote", out, build(locale).destinations.length);
}
